H('343.d.1.B',4,"An early childhood professional who adapts activities to each child's pace shows:","flexibility and respect for individual needs",["rigidity","favoritism","disinterest"],"Individualization is a mark of quality.")
H('343.d.1.C',3,"A written statement of an early childhood teacher's beliefs about how children learn is a:","philosophy statement",["lesson sequence","fire drill plan","budget"],"Philosophy statements express beliefs.")
H('343.d.1.C',4,"A teacher who writes that children learn through play is expressing a:","professional belief about learning",["school rule","state law","grade requirement"],"Beliefs guide practice.")
H('343.d.1.D',3,"Which credential is commonly earned by early childhood professionals?","Child Development Associate (CDA)",["Commercial pilot license","Master electrician license","Law license"],"The CDA is a widely recognized credential.")
H('343.d.1.D',4,"An associate degree in early childhood education usually takes about:","two years",["six months","eight years","one week"],"Associate degrees take about two years.")
H('343.d.1.E',3,"A personal career plan for early childhood should include:","education goals, experiences, and timelines",["lunch choices","social media posts","pet names"],"Plans map steps to goals.")
H('343.d.1.E',4,"Reviewing and revising a career plan each year helps a student:","stay on track as goals and opportunities change",["avoid goals","stop learning","ignore options"],"Plans should evolve.")
H('343.d.1.F',3,"Which is an early childhood career opportunity?","Head Start teacher",["Air traffic controller","Welder","Chemical engineer"],"Head Start employs early educators.")
H('343.d.1.F',4,"Besides teaching, an early childhood degree can lead to a job as a:","child care center director",["pharmacist","mechanic","court reporter"],"Directors manage programs.")
H('343.d.1.G',3,"Special education, bilingual education, and speech-language pathology are examples of:","high-need teaching specialty areas",["optional hobbies","lunch roles","school clubs"],"These fields have shortages.")
H('343.d.1.G',4,"Districts often offer incentives for teachers in shortage areas because there are:","too few qualified candidates to fill the positions",["too many applicants","no students","no budget"],"Incentives attract needed teachers.")
H('343.d.2.A',3,"A teacher who plans short, active lessons for four-year-olds is applying knowledge of:","child development",["tax law","engine repair","accounting"],"Development guides planning.")
H('343.d.2.A',4,"Reflecting on how a lesson fit the children's developmental level helps a teacher:","improve future planning",["avoid feedback","skip assessment","repeat errors"],"Reflection improves practice.")
H('343.d.2.B',3,"Children learn best through hands-on, play-based experiences, according to:","constructivist theory",["lecture-only theory","fatalism","traditional drill theory"],"Constructivism values active exploration.")
H('343.d.2.B',4,"A teacher who lets children explore water and measuring cups is applying the idea that children:","construct knowledge through active experience",["learn only by listening","learn only by copying","learn only from worksheets"],"Exploration builds understanding.")
H('343.d.2.C',3,"A teacher who gets down to a child's eye level when speaking is showing behavior that:","builds connection and attention",["frightens children","ends communication","shows disinterest"],"Eye-level contact helps young children.")
H('343.d.2.C',4,"Teacher enthusiasm tends to:","increase children's engagement",["reduce curiosity","lower participation","end learning"],"Enthusiasm is contagious.")
H('343.d.2.D',3,"Giving clear one-step directions to young children is a teaching skill because it:","matches their ability to follow instructions",["confuses them","slows learning","ignores their needs"],"Simple directions fit their development.")
H('343.d.2.D',4,"Modeling how to wash hands, then letting children practice, is the teaching skill of:","demonstration with guided practice",["silent supervision","testing","punishment"],"Show, then practice.")
H('343.d.2.E',3,"A teacher adds picture cards for a child with a language delay. This is an instructional accommodation that:","supports understanding",["removes the lesson","isolates the child","lowers the goal permanently"],"Visuals support comprehension.")
H('343.d.2.E',4,"Offering a child with limited fine motor skills a larger crayon is an example of:","adapting materials to the child's needs",["lowering standards for all","punishing the child","skipping the activity"],"Adaptations remove barriers.")
H('343.d.3.A',3,"Daily outdoor play promotes young children's:","physical health and gross motor development",["tax knowledge","reading speed only","silence"],"Outdoor play builds the body.")
H('343.d.3.A',4,"Singing songs with hand motions promotes:","language and coordination",["isolation","fear","boredom"],"Songs combine words and movement.")
H('343.d.3.B',3,"An age-appropriate lesson plan for three-year-olds should include:","short, hands-on activities",["long lectures","timed tests","reading assignments"],"Three-year-olds learn by doing.")
H('343.d.3.B',4,"Instructional materials for toddlers should be:","safe, durable, and too large to swallow",["very small","fragile","sharp"],"Safety comes first.")
H('343.d.3.C',3,"A teacher notices children lose interest after five minutes of a story. This suggests the lesson should be:","shortened or made more interactive",["lengthened","repeated unchanged","cancelled forever"],"Adjust to attention spans.")
H('343.d.3.C',4,"Which evidence best shows a lesson was effective?","Children can demonstrate the skill the lesson targeted",["The room was quiet","The lesson was long","The teacher was tired"],"Effectiveness is measured by learning.")
H('343.d.3.D',3,"Feedback from a mentor teacher can guide a student teacher in selecting:","more effective activities and strategies",["lunch menus","bus routes","wall colors"],"Feedback improves choices.")
H('343.d.3.D',4,"A parent says her child loves counting songs. A teacher can use this feedback to:","include more music in math activities",["remove songs","avoid math","ignore the parent"],"Family input guides planning.")
H('343.d.4.A',3,"A safe early childhood classroom has:","covered outlets, secured shelves, and clear pathways",["open cabinets of cleaners","cords across the floor","blocked exits"],"Safety features prevent injuries.")
H('343.d.4.A',4,"Teachers check the playground each morning to:","find and remove hazards before children arrive",["decorate it","paint lines","count balls"],"Daily inspections prevent accidents.")
H('343.d.4.B',3,"A predictable daily schedule helps young children by:","giving them security and routine",["creating confusion","removing structure","increasing anxiety"],"Routines make children feel safe.")
H('343.d.4.B',4,"Rotating toys and materials regularly helps keep children:","interested and engaged",["bored","distracted always","unsafe"],"Novelty sustains interest.")
H('343.d.4.C',3,"A transition song to signal clean-up time is a technique that:","helps children move smoothly between activities",["causes chaos","delays lunch","ends play"],"Songs cue transitions.")
H('343.d.4.C',4,"Giving a two-minute warning before a transition helps children:","prepare to stop an activity",["ignore the teacher","forget the rules","feel rushed"],"Warnings ease changes.")
H('343.d.4.D',3,"Two preschoolers want the same truck. A teacher supporting conflict resolution would:","help them name feelings and find a way to share or take turns",["take the truck away silently","punish the older child","ignore them"],"Guided problem solving teaches skills.")
H('343.d.4.D',4,"Teaching children to say I need a turn, please supports:","peaceful problem solving",["tattling","aggression","avoidance"],"Words replace conflict.")
H('343.d.5.A',3,"Which is an informal assessment in a preschool?","Observing a child sort shapes",["Standardized state test","College entrance exam","Final exam"],"Observation is informal assessment.")
H('343.d.5.A',4,"A developmental screening checklist is used to:","identify children who may need further evaluation",["rank children","decide lunch","assign grades"],"Screening flags possible delays.")
H('343.d.5.B',3,"If many children cannot recognize their names, the teacher should:","add more name-recognition activities",["stop teaching names","ignore the data","punish the class"],"Data should shape instruction.")
H('343.d.5.B',4,"Tracking each child's progress over time in a portfolio helps teachers:","plan individualized instruction",["compare children harshly","avoid parent contact","reduce observation"],"Portfolios show growth.")
H('343.d.6.A',3,"A teacher who connects a family with a food bank is using:","community resources to support families",["school discipline","grade reports","teacher evaluation"],"Resources help families.")
H('343.d.6.A',4,"Early Childhood Intervention (ECI) in Texas provides services to:","infants and toddlers with developmental delays",["high school athletes","college students","adults"],"ECI serves children birth to age three.")
H('343.d.6.B',3,"Inviting parents to volunteer in the classroom builds:","positive home-school partnerships",["distance","mistrust","competition"],"Involvement strengthens bonds.")
H('343.d.6.B',4,"A newsletter that shares what children are learning helps families:","continue learning at home",["avoid school","skip events","ignore progress"],"Communication links home and school.")
H('343.d.6.C',3,"Sharing teaching ideas with other early childhood teachers is part of a:","professional learning community",["bus route","cafeteria line","parent pickup"],"PLCs support teacher growth.")
H('343.d.6.C',4,"A speech therapist and a classroom teacher working together for a child is an example of:","professional collaboration",["competition","isolation","duplication"],"Teams support children.")
H('343.d.7.A',3,"A communication board with pictures helps a child who:","has difficulty speaking",["is learning to drive","likes music","is tall"],"AAC supports communication.")
H('343.d.7.A',4,"A switch-adapted toy allows a child with limited movement to:","participate in play independently",["avoid play","watch only","wait for help always"],"Adaptations promote independence.")
H('343.d.7.B',3,"A touch-screen learning app for preschoolers should be:","interactive, age-appropriate, and used in moderation",["violent and fast","unlimited","ad-filled"],"Quality and limits matter.")
H('343.d.7.B',4,"Using a digital camera to document children's learning helps teachers:","share progress with families",["avoid observation","replace teaching","hide data"],"Photos document growth.")
H('343.d.8.A',3,"Speaking respectfully to families about their child demonstrates:","effective interaction skills",["poor communication","bias","carelessness"],"Respect builds trust.")
H('343.d.8.A',4,"Active listening during a parent conference includes:","restating concerns and asking clarifying questions",["interrupting","checking the phone","changing the subject"],"Listening shows respect.")
H('343.d.8.B',3,"An early childhood teacher must treat information about a child's family as:","confidential",["public","a topic for lunchroom talk","social media content"],"Confidentiality is an ethical duty.")
H('343.d.8.B',4,"NAEYC's Code of Ethical Conduct is a guide for:","early childhood professionals' decisions",["bus drivers","bankers","police officers"],"The code guides early educators.")
H('343.d.8.C',3,"A parent asks a teacher not to tell the director about a child's injury. The teacher should:","follow policy and report the injury",["hide it","falsify records","tell no one"],"Injuries must be reported.")
H('343.d.8.C',4,"A coworker leaves a classroom unsupervised. The ethical response is to:","address it with the coworker or report it to ensure children's safety",["join in","ignore it","post about it"],"Supervision is non-negotiable.")
H('343.d.9.A',3,"Early childhood teachers can grow professionally by:","attending workshops and earning continuing education hours",["avoiding training","working alone","ignoring research"],"Ongoing learning is expected.")
H('343.d.9.A',4,"Many child care licensing rules require staff to complete annual:","training hours",["vacations","relocations","sports events"],"Licensing requires yearly training.")
H('343.d.9.B',3,"A short-term professional growth goal might be to:","attend a workshop on guidance this semester",["become a state director in a year","retire next month","change careers daily"],"Short-term goals are reachable soon.")
H('343.d.9.B',4,"A long-term professional goal for an early childhood teacher could be to:","earn a bachelor's degree and teacher certification",["finish this week's lesson plan","attend lunch","sign in today"],"Long-term goals take years.")
H('343.d.10.A',3,"Accurate personnel and child records in a child care program are needed for:","licensing compliance and safety",["decoration","gossip","advertising"],"Records prove compliance.")
H('343.d.10.A',4,"Attendance records in a child care center are important because they:","show who is present in an emergency",["decide naptime","set tuition rates","pick snacks"],"Attendance guides emergency accounting.")
H('343.d.10.B',3,"A good child care meal plan includes:","whole grains, fruits, vegetables, and lean protein",["only desserts","only fried foods","only juice"],"Variety supports health.")
H('343.d.10.B',4,"Planning menus around allergies means:","avoiding or substituting foods that children are allergic to",["serving allergens to all","ignoring parents","hiding ingredients"],"Allergy safety is critical.")
H('343.d.10.C',3,"A child care director has a limited budget. A sound practice is to:","plan spending on priorities like safety and staffing first",["spend on decorations first","ignore costs","skip records"],"Priorities guide budgets.")
H('343.d.10.C',4,"Tuition, grants, and food program reimbursements are common:","sources of revenue for a child care program",["causes of loss","kinds of toys","safety rules"],"These fund operations.")
H('343.d.10.D',3,"Which is a required safety procedure in child care centers?","Regular fire and emergency drills",["Optional naptime","Free play only","Weekly parties"],"Drills are required.")
H('343.d.10.D',4,"A caregiver should know where the first aid kit and emergency contact numbers are so they can:","respond quickly to an emergency",["decorate the room","plan menus","count children later"],"Preparation saves time.")
H('343.d.11.A',3,"A practicum student leads circle time with the supervising teacher present. This is:","applying instructional strategies in a real classroom",["a simulation only","a field trip","a staff party"],"Practicum applies skills in context.")
H('343.d.11.A',4,"During practicum, a student should follow the host center's:","policies and procedures",["personal preferences","guesses","rumors"],"Students follow site rules.")
H('343.d.11.B',3,"A practicum student writes about how a story activity went and what to change. This is:","reflection on an instructional experience",["a lunch order","a permission slip","an invoice"],"Reflection improves practice.")
H('343.d.11.B',4,"Documenting instructional experiences with dates and details helps a student:","track growth and support portfolio entries",["avoid reflection","hide errors","skip observation"],"Records show progress.")
H('343.d.12.A',3,"An artifact showing technical skill in early childhood might be:","a learning center plan you designed",["a menu from a restaurant","a ticket stub","a sports score"],"Artifacts show skills.")
H('343.d.12.A',4,"Documentation that supports attainment of technical skills includes:","signed evaluations from a supervising teacher",["social media likes","personal opinions","hallway rumors"],"Evaluations verify skills.")
H('343.d.12.B',3,"A professional portfolio for an early childhood career should be updated:","regularly as new skills and experiences are gained",["never","only once","after retirement"],"Portfolios stay current.")
H('343.d.12.B',4,"Adding a recent CPR certification to a portfolio shows:","current training and qualifications",["unrelated hobbies","old resume items only","personal opinions"],"Certifications show qualifications.")
H('343.d.12.C',3,"At a portfolio presentation to a director, a student should:","organize items logically and explain what each shows",["read silently","skip items","argue"],"Clear explanation shows skill.")
H('343.d.12.C',4,"A student asked a tough question in a portfolio review should respond:","honestly and thoughtfully",["defensively","evasively","angrily"],"Honest answers build credibility.")

# ---- 344 Extended Practicum in Early Childhood Education ----
H('344.d.2',3,"A practicum student sees that children often argue during block play. A strong advanced problem-solving approach is to:","observe, identify causes, try a solution, and evaluate results",["wait for the problem to disappear","remove blocks permanently","blame the children"],"Systematic problem solving follows observe, act, evaluate.")
H('344.d.2',4,"After trying a new strategy to reduce clean-up chaos, the next problem-solving step is to:","evaluate whether the strategy worked and adjust",["stop observing","repeat it unchanged","hide the data"],"Evaluation closes the problem-solving loop.")
H('344.d.1.A',3,"A teacher smiles, kneels, and speaks in a calm voice to a nervous child. This combines:","verbal and non-verbal communication",["only written communication","only silence","only gestures without words"],"Tone and body language work together.")
H('344.d.1.A',4,"Which non-verbal behavior shows that a teacher is listening to a parent?","Eye contact and nodding",["Crossing arms and sighing","Looking at the clock","Turning away"],"Attentive body language shows respect.")
H('344.d.1.B',3,"Explaining the day's plan to children during circle time is an example of presenting information:","informally",["in a board report","in a legal brief","in a research article"],"Circle time is casual and conversational.")
H('344.d.1.B',4,"A formal presentation to the center's board about a new literacy program should include:","organized goals, evidence, and a clear conclusion",["jokes only","unrelated stories","random notes"],"Formal talks are structured.")
H('344.d.1.C',3,"A teacher charts how many children can count to ten and shares a summary with parents. This is:","analyzing and communicating information",["ignoring data","guessing","hiding results"],"Data are interpreted and shared.")
H('344.d.1.C',4,"When sharing assessment results with families, a teacher should:","explain what the results mean in plain language",["use only technical terms","share other children's scores","avoid questions"],"Plain language aids understanding.")
H('344.d.1.D',3,"A teacher repeats a parent's concern in her own words to be sure she understood. This is:","clarifying through active listening",["interrupting","ending the talk","judging"],"Paraphrasing confirms meaning.")
H('344.d.1.D',4,"Which response shows active listening?","So you are worried about naptime at home?",["That's not my job.","I'm busy.","You're wrong."],"Reflecting back shows you heard.")
H('344.d.3.A',3,"A practicum student arrives early, completes assigned tasks, and asks how to help. This shows:","a positive, productive work ethic",["poor attitude","avoidance","carelessness"],"Initiative reflects work ethic.")
H('344.d.3.A',4,"Meeting deadlines for lesson plans shows:","dependability",["indifference","disorganization","avoidance"],"Reliability matters in practicum.")
H('344.d.3.B',3,"A student sees a classmate falsify a practicum time log. Integrity requires the student to:","refuse to participate and report it to the supervisor",["copy the log","ignore it","help hide it"],"Honesty comes first.")
H('344.d.3.B',4,"Choosing the ethical course of action means doing what is right even when it is:","inconvenient or unpopular",["easy","free","secret"],"Integrity is tested when it is hard.")
H('344.d.3.C',3,"Using a classroom computer for personal shopping during work time violates:","the acceptable-use policy",["the lunch schedule","the fire code","the bus route"],"AUPs limit personal use.")
H('344.d.3.C',4,"Professional etiquette in a child care center includes:","silencing personal phones during supervision",["texting during class","posting children's photos publicly","gossiping with parents"],"Focus on children is required.")
H('344.d.3.D',3,"A practicum student follows the required adult-to-child ratio because it is:","a licensing regulation",["a suggestion","optional","a game rule"],"Ratios are legally required.")
H('344.d.3.D',4,"Complying with mandated reporting laws means reporting suspected abuse:","to the proper authorities, even if unsure",["only if certain","never","after a year"],"Reasonable suspicion triggers reporting.")
H('344.d.4.A',3,"Using open-ended questions with a small group is an instructional strategy that:","invites children to explain their thinking",["silences children","limits language","tests memorization only"],"Open questions build language and reasoning.")
H('344.d.4.A',4,"With increased fluency, a practicum student can move from following a script to:","adapting the lesson to children's responses",["avoiding lesson plans","copying other teachers","skipping steps"],"Fluency allows responsive teaching.")
H('344.d.4.B',3,"Planning activities that start where children are and stretch them slightly applies:","Vygotsky's zone of proximal development",["random sequencing","a lunch schedule","a fire plan"],"The ZPD guides challenge level.")
H('344.d.4.B',4,"Maslow's hierarchy reminds teachers that children learn best when their basic needs for:","safety and food are met",["entertainment are met first","homework are met","fashion are met"],"Basic needs come before learning.")
H('344.d.4.C',3,"A teacher builds a unit on community helpers with books, props, and visits. This is developing:","curriculum and supporting materials",["a menu","a budget","a staff schedule"],"Units combine goals and materials.")
H('344.d.4.C',4,"Materials for a curriculum unit should be:","aligned with learning goals and developmentally appropriate",["random","expensive only","inappropriate"],"Materials must serve the objectives.")
H('344.d.4.D',3,"Foundation subjects in early childhood include:","language arts and math",["car repair","accounting","welding"],"Early literacy and math are foundational.")
H('344.d.4.D',4,"Art, music, and movement are examples of:","enrichment subject areas",["unnecessary distractions","discipline methods","assessment forms"],"Enrichment broadens development.")
H('344.d.4.E',3,"A complete early childhood lesson plan includes:","objectives, materials, procedures, and assessment",["lunch prices","bus rosters","staff birthdays"],"Plans link goals and evidence.")
H('344.d.4.E',4,"The objective that children will sort objects by color is best assessed by:","observing children sort a set of objects",["asking about lunch","counting absences","checking shoes"],"Assess the skill directly.")
H('344.d.4.F',3,"Reflecting on a lesson by asking what to change is part of:","self-assessment",["lunch duty","fire drills","enrollment"],"Reflection improves teaching.")
H('344.d.4.F',4,"A reflection log is most useful when entries are:","specific and followed by action steps",["vague and rare","gossip","deleted"],"Specifics lead to growth.")
H('344.d.4.G',3,"A work sample for a practicum portfolio could be:","a thematic unit plan you created",["a menu from home","a vacation photo","a bill"],"Work samples show your skills.")
H('344.d.4.G',4,"Work samples must be:","your own original work",["copied from others","unrelated to your goals","anonymous"],"Samples must be authentic.")

# ---- 345 Practicum in Education and Training (Extended) ----
H('345.d.1.A',3,"A teacher is irritable, exhausted, and frequently ill during testing season. This pattern suggests:","burnout risk from prolonged stress",["increased wellness","good boundaries","job mastery"],"Prolonged stress leads to burnout.")
H('345.d.1.A',4,"Which is a common physical symptom of anxiety in educators?","Racing heart and tight muscles",["Calm breathing","Steady energy","Improved appetite"],"Anxiety has physical symptoms.")
H('345.d.1.B',3,"Telling parents you will respond to emails within 24 hours on school days sets a:","reasonable communication boundary",["rude barrier","grading rule","safety rule"],"Clear expectations protect time.")
H('345.d.1.B',4,"Which action best protects a teacher's personal time?","Setting a daily stopping point for work tasks",["Taking work everywhere","Answering all messages instantly","Never taking breaks"],"Stopping points create balance.")
H('345.d.1.C',3,"Mindfulness breaks, walks, and adequate sleep are strategies to manage:","teacher health and wellness",["budget cuts","bus delays","class size"],"Self-care supports resilience.")
H('345.d.1.C',4,"A teacher who schedules planning time during the school day to avoid evening work is managing:","workload and stress",["student discipline","testing windows","fire drills"],"Time management reduces stress.")
H('345.d.2.A',3,"Changes in state funding for schools are an example of which kind of influence on education?","Economic and political",["Athletic","Cafeteria","Janitorial"],"Funding is shaped by politics and the economy.")
H('345.d.2.A',4,"The use of artificial intelligence tools by students is a current issue because it affects:","how teachers design and assess assignments",["bus schedules","building colors","lunch menus"],"AI changes assessment design.")
H('345.d.2.B',3,"Which practice do effective teachers use?","Setting high expectations and giving timely feedback",["Lecturing only","Ignoring questions","Grading randomly"],"Expectations and feedback drive learning.")
H('345.d.2.B',4,"Effective trainers in business settings check for understanding by:","asking learners to demonstrate the skill",["assuming everyone understands","reading slides aloud","ending early"],"Demonstration shows mastery.")
H('345.d.2.C',3,"A school with a safe climate, strong leadership, and clear goals is most likely:","an effective school",["a failing school","a private school","a charter school"],"These traits characterize effective schools.")
H('345.d.2.C',4,"Data-driven decision making in an effective school means leaders:","use student data to guide improvement",["ignore results","guess","avoid evidence"],"Evidence guides improvement.")
H('345.d.2.D',3,"A teacher's written beliefs about education should reflect:","personal values about teaching and learning",["school lunch policy","district bus rules","parking rules"],"Philosophy is personal and professional.")
H('345.d.2.D',4,"A belief statement is most useful when it includes:","examples of how the teacher will act on those beliefs",["only slogans","unrelated quotes","fiction"],"Examples turn beliefs into practice.")
H('345.d.2.E',3,"Most Texas public school teachers must hold at least a:","bachelor's degree",["high school diploma only","doctorate","trade certificate"],"A bachelor's degree is the baseline.")
H('345.d.2.E',4,"Teachers who want to become principals typically earn a:","master's degree and administrator certification",["welding certificate","cosmetology license","pilot license"],"Administration requires advanced preparation.")
H('345.d.2.F',3,"A career plan for teaching should list steps such as:","degree, certification exam, and first job",["lunch period","parking spot","club jersey"],"Plans list concrete milestones.")
H('345.d.2.F',4,"Job shadowing a teacher helps a student refine a career plan by:","showing what the daily work is really like",["avoiding the job","guaranteeing a job","replacing coursework"],"Experience informs decisions.")
H('345.d.2.G',3,"A fitness instructor who teaches classes at a gym is working in:","a non-traditional teaching setting",["a school board","a district office","a government lab"],"Teaching happens outside schools too.")
H('345.d.2.G',4,"Which is a training career outside public schools?","Corporate learning and development specialist",["School bus monitor","Lunchroom aide","Crossing guard"],"Companies employ trainers.")
H('345.d.2.H',3,"Teacher shortages in Texas are often greatest in:","bilingual education, special education, and STEM",["recess supervision","cafeteria management","yearbook"],"These fields have the most openings.")
H('345.d.2.H',4,"A student interested in a shortage area can benefit from:","incentives such as loan forgiveness and stipends",["reduced job openings","longer degrees","no support"],"Incentives attract candidates.")
H('345.d.3.A',3,"A middle school teacher knows early adolescents crave peer acceptance, so the teacher plans:","collaborative group activities",["only silent seat work","isolated tasks","competitive elimination"],"Group work fits social needs.")
H('345.d.3.A',4,"Erikson's stage of identity versus role confusion suggests high school students benefit from:","opportunities to explore interests and values",["strict conformity","isolation","fewer choices"],"Teens form identity through exploration.")
H('345.d.3.B',3,"A teacher who uses spaced practice and retrieval quizzes is applying research on:","memory and retention",["school finance","building safety","bus routes"],"Spacing and retrieval strengthen memory.")
H('345.d.3.B',4,"Constructivism holds that learners:","build understanding by connecting new ideas to prior experience",["absorb facts passively","learn only by memorizing","learn only from lectures"],"Learners construct meaning.")
H('345.d.3.C',3,"Teacher expectations influence student performance because students often:","rise or fall to the expectations set for them",["ignore expectations","never notice them","perform identically"],"Expectations shape effort.")
H('345.d.3.C',4,"A teacher who consistently enforces rules fairly builds:","student trust and a respectful climate",["resentment","chaos","fear of speaking"],"Fairness builds trust.")
H('345.d.3.D',3,"Giving a clear lesson opening, explanation, and closing is the teaching skill of:","structuring a lesson",["avoiding planning","filling time","random teaching"],"Structure supports learning.")
H('345.d.3.D',4,"A teacher who restates a student's confusing answer and builds on it demonstrates the skill of:","responsive questioning",["ignoring students","ending discussion","dismissing ideas"],"Building on responses extends thinking.")
H('345.d.3.E',3,"Providing graphic organizers for students who struggle to organize writing is a:","scaffold that supports learning",["penalty","distraction","reward"],"Scaffolds help students succeed.")
H('345.d.3.E',4,"Tiered assignments allow students to:","work at appropriate challenge levels on the same topic",["work on different subjects","skip learning","avoid assessments"],"Tiering differentiates difficulty.")
H('345.d.4.A',3,"An email to a parent that begins with a positive note, states the concern, and proposes next steps shows effective:","stakeholder communication",["gossip","avoidance","confrontation"],"Positive, solution-focused messages work.")
H('345.d.4.A',4,"When disagreeing with an administrator's decision, a teacher should:","express concerns respectfully and offer solutions",["complain to students","ignore the decision","post it online"],"Professional disagreement is respectful.")
H('345.d.4.B',3,"Reading across content areas promotes:","literacy",["fatigue","avoidance","isolation"],"Reading in every subject builds literacy.")
H('345.d.4.B',4,"A science teacher has students interpret data tables and graphs. This promotes:","numeracy",["penmanship","silence","tardiness"],"Reading data builds numeracy.")
H('345.d.5.A',3,"Universal Design for Learning (UDL) suggests teachers provide:","multiple ways to engage, represent, and express learning",["one method for all","only lectures","only tests"],"UDL offers flexible options.")
H('345.d.5.A',4,"Gagne's nine events of instruction organize a lesson beginning with:","gaining attention",["assigning homework","giving the final test","dismissal"],"The first event is gaining attention.")
H('345.d.5.B',3,"A scope and sequence shows:","what will be taught and in what order across the year",["bus schedules","lunch menus","fire exits"],"It maps content over time.")
H('345.d.5.B',4,"A unit plan is longer than a lesson plan because it covers:","a series of related lessons around a big idea",["a single worksheet","a bell schedule","one student"],"Units organize multiple lessons.")
H('345.d.5.C',3,"To make sure a worksheet aligns with the TEKS, a teacher checks that it:","targets the skills listed in the standards",["is colorful","is long","is copied from last year"],"Alignment means matching standards.")
H('345.d.5.C',4,"Which resource would best align with a TEKS-based reading objective?","A text at the right grade-level complexity with questions tied to the standard",["A random video","An unrelated puzzle","A game with no content"],"Materials must target the standard.")
H('345.d.5.D',3,"The foundation curriculum in Texas includes:","English language arts, math, science, and social studies",["only art and music","only gym","only lunch"],"Foundation subjects are the core.")
H('345.d.5.D',4,"Enrichment subjects such as fine arts and CTE:","broaden students' skills and interests",["replace core subjects","are unnecessary","lack standards"],"Enrichment adds breadth.")
H('345.d.5.E',3,"A research-based practice is one that:","studies show improves student learning",["is popular on social media","a teacher likes","was used last year"],"Evidence defines research-based.")
H('345.d.5.E',4,"Using formative assessment to guide instruction is research-based because studies show it:","raises student achievement",["lowers motivation","increases workload only","has no effect"],"Formative assessment improves outcomes.")
H('345.d.5.F',3,"A teacher tries direct instruction, then compares results with cooperative learning. This is analyzing:","the effectiveness of instructional strategies",["lunch counts","bus routes","attendance"],"Comparing strategies informs choices.")
H('345.d.5.F',4,"Which strategy can help students retain information?","Retrieval practice",["Skipping review","Cramming only","Passive listening only"],"Retrieval strengthens memory.")
H('345.d.5.G',3,"To evaluate a lesson plan after teaching it, a teacher should compare student results to the:","learning objective",["lunch schedule","bus route","seating chart"],"Objectives define success.")
H('345.d.5.G',4,"A lesson plan needs revision if:","assessment shows students did not master the objective",["students were quiet","the room was cold","it was short"],"Results drive revision.")
H('345.d.5.H',3,"Student feedback on which activities helped them learn can guide a teacher's:","choice of future strategies",["bus assignment","lunch time","parking"],"Feedback shapes selection.")
H('345.d.5.H',4,"Peer observation feedback helps a teacher decide:","which strategies to keep, adjust, or drop",["which room to use","which lunch to serve","which bus to ride"],"Observers offer fresh insight.")
H('345.d.6.A',3,"Universal design in a classroom means arranging space so:","all students, including those with disabilities, can access it",["only some students can move","furniture is blocked","seating is random"],"Accessible design benefits all.")
H('345.d.6.A',4,"Wide aisles and labeled materials support a classroom that is:","accessible and organized",["cluttered","confusing","unsafe"],"Accessibility and organization help learning.")
H('345.d.6.B',3,"Greeting students at the door and starting with a warm-up sets:","a positive, focused tone",["a negative tone","chaos","delay"],"Routines set the climate.")
H('345.d.6.B',4,"Posting learning objectives helps students:","know what they are expected to learn",["guess grades","avoid tasks","skip class"],"Objectives provide clarity.")
H('345.d.6.C',3,"Consistent consequences applied fairly help a teacher:","maintain order and trust",["increase conflict","lose control","confuse students"],"Consistency builds order.")
H('345.d.6.C',4,"A teacher gives a nonverbal signal, such as raising a hand, to get attention. This management technique:","saves time and avoids shouting",["creates noise","wastes time","angers students"],"Signals are efficient.")
H('345.d.6.D',3,"In peer mediation, trained students help classmates:","talk through a conflict and reach an agreement",["get punished","avoid each other","report grades"],"Mediators facilitate agreement.")
H('345.d.6.D',4,"A teacher mediating a dispute should remain:","neutral and focused on solutions",["biased","angry","silent"],"Neutrality builds trust.")
H('345.d.7.A',3,"A unit test at the end of a chapter is a:","summative assessment",["formative assessment","pre-assessment","attendance check"],"Summative tests measure learning at the end.")
H('345.d.7.A',4,"A thumbs-up or thumbs-down check during a lesson is a:","formative assessment",["summative assessment","final exam","state test"],"Quick checks guide instruction.")
H('345.d.7.B',3,"Student self-assessment promotes growth because it teaches students to:","identify their strengths and next steps",["blame teachers","avoid goals","compare only"],"Self-assessment builds ownership.")
H('345.d.7.B',4,"Goal-setting conferences based on assessment results help students:","take ownership of their learning",["avoid work","ignore feedback","stop trying"],"Ownership drives motivation.")
H('345.d.7.C',3,"A teacher who journals after each lesson is using:","self-reflection",["lesson avoidance","gossip","grading shortcuts"],"Journals promote reflection.")
H('345.d.7.C',4,"Video-recording a lesson and watching it later supports growth by:","revealing habits that are hard to notice while teaching",["wasting time","replacing planning","embarrassing students"],"Video reveals blind spots.")
H('345.d.7.D',3,"Standardized test results can help a teacher:","identify skills that need more instruction",["choose lunch","pick friends","assign seats randomly"],"Results show gaps.")
H('345.d.7.D',4,"Disaggregating data means:","breaking results into subgroups to find gaps",["combining all scores into one","hiding results","deleting scores"],"Subgroup analysis reveals equity gaps.")
H('345.d.8.A',3,"A teacher who speaks to the school board about class sizes is:","advocating for students and learning",["ignoring problems","avoiding policy","punishing students"],"Advocacy speaks up for students.")
H('345.d.8.A',4,"Advocating for a student with a disability can include:","making sure the student's accommodations are provided",["removing services","ignoring the IEP","lowering expectations automatically"],"Advocacy ensures supports are delivered.")
H('345.d.8.B',3,"A teacher refers a family to the school counselor for help with housing. The teacher is using:","school and community resources",["punishment","testing","grade changes"],"Counselors connect families to help.")
H('345.d.8.B',4,"Community resources that can support students include:","food banks, libraries, and tutoring programs",["casinos","bars","nightclubs"],"These organizations serve families.")
H('345.d.8.C',3,"A teacher who calls home with good news builds:","positive relationships with families",["distrust","distance","conflict"],"Positive contact builds trust.")
H('345.d.8.C',4,"School-wide events such as family science nights help partnerships by:","involving families in learning",["excluding families","limiting access","avoiding communication"],"Events bring families in.")
H('345.d.9.A',3,"A teacher chooses a digital timeline tool for a history lesson because it:","helps students organize events in order",["replaces reading","adds noise","limits thinking"],"Tools should serve the content.")
H('345.d.9.A',4,"Before assigning an online tool, a teacher should confirm it works on:","the devices students actually have",["only the teacher's phone","no devices","an outdated system"],"Access matters.")
H('345.d.9.B',3,"Using an online quiz tool that gives instant results integrates technology into:","evaluation",["lunch","busing","attendance only"],"Instant results support assessment.")
H('345.d.9.B',4,"A class website that posts homework and announcements improves:","communication with students and families",["secrecy","confusion","delay"],"Websites keep everyone informed.")
H('345.d.10.A',3,"A teacher who gives every student equal chances to participate is demonstrating:","fairness",["bias","favoritism","exclusion"],"Equity of participation is professional.")
H('345.d.10.A',4,"Which behavior shows professionalism on social media?","Keeping posts appropriate and not sharing student information",["Posting student grades","Complaining about students","Sharing rumors"],"Professionals protect privacy.")
H('345.d.10.B',3,"The Texas Educators' Code of Ethics sets standards for:","professional conduct of educators",["school menus","bus drivers only","sports rules"],"The code governs educator conduct.")
H('345.d.10.B',4,"Teachers are mandated reporters, meaning they must report:","suspected abuse or neglect",["all discipline","all grades","all absences"],"Mandated reporters protect children.")
H('345.d.10.C',3,"A teacher is offered a tutoring fee to give a student a better grade. Ethical practice is to:","refuse and follow district policy",["accept it","hide it","ask for more"],"Grades must reflect merit.")
H('345.d.10.C',4,"A teacher finds out a colleague is sharing test questions early with some students. The ethical response is to:","report the matter to administration",["join in","ignore it","tell students"],"Test security is an ethical duty.")
H('345.d.10.D',3,"Non-compliance with the Code of Ethics can result in:","sanctions such as certificate suspension or revocation",["a school award","a longer break","a bonus"],"Sanctions follow serious violations.")
H('345.d.10.D',4,"A teacher's certificate may be revoked for:","serious misconduct such as an improper relationship with a student",["arriving one minute late once","changing a bulletin board","using a new textbook"],"Serious violations carry serious penalties.")
H('345.d.11.A',3,"Which is a resource for teachers' professional development?","Education service center workshops",["Cafeteria menus","Bus routes","Parking permits"],"ESCs offer training.")
H('345.d.11.A',4,"Professional learning communities help teachers by:","sharing practices and analyzing student data together",["working alone","avoiding feedback","hiding results"],"Collaboration improves practice.")
H('345.d.11.B',3,"A teacher who reads research and tries new strategies is demonstrating:","ongoing professional growth",["stagnation","avoidance","complacency"],"Growth is continuous.")
H('345.d.11.B',4,"Attending a conference and then sharing what was learned with colleagues:","extends the benefit of the training",["wastes time","hides learning","reduces collaboration"],"Sharing multiplies impact.")
H('345.d.11.C',3,"A professional growth plan should include:","specific goals, actions, and timelines",["vague wishes","no deadlines","only complaints"],"Specific plans are actionable.")
H('345.d.11.C',4,"A teacher whose data show weak writing results sets a goal to learn writing workshop methods. This goal is:","tied to student needs",["unrelated to teaching","random","personal only"],"Goals should address student needs.")
H('345.d.12.A',3,"During a practicum, a student teacher uses a think-pair-share with a class. This applies:","an instructional strategy in a real classroom",["a school rule","a bus plan","a lunch routine"],"Practicum applies strategies.")
H('345.d.12.A',4,"A practicum student should seek feedback after teaching from the:","cooperating teacher",["cafeteria staff","visitors","janitor"],"The cooperating teacher observes and advises.")
H('345.d.12.B',3,"A reflective journal entry should describe what happened, why it mattered, and:","what the teacher will do next",["lunch choices","grades of friends","weather forecasts"],"Reflection ends with action.")
H('345.d.12.B',4,"Keeping a log of practicum hours and activities supports:","accountability and portfolio evidence",["avoidance","secrecy","errors"],"Logs prove participation.")
H('345.d.13.A',3,"Evidence that shows a student's technical skills in teaching could be:","an observation report completed by a supervising teacher",["a vacation photo","a concert ticket","a gift receipt"],"Observation reports document skill.")
H('345.d.13.A',4,"Artifacts in a portfolio should be:","relevant, organized, and labeled",["random and unlabeled","unrelated","outdated only"],"Good artifacts are curated.")
H('345.d.13.B',3,"Updating a teaching resume to include practicum experience shows:","recent and relevant experience",["old information","irrelevant details","hobbies only"],"Resumes should reflect current experience.")
H('345.d.13.B',4,"A teaching portfolio's philosophy statement should be:","revised as beliefs and experience grow",["never changed","copied from others","left blank"],"Philosophies evolve.")
H('345.d.13.C',3,"A professional portfolio presentation to a hiring panel is an opportunity to:","demonstrate qualifications and communication skills",["avoid questions","read silently","hide work"],"Presentations showcase skills.")
H('345.d.13.C',4,"Preparing talking points before a portfolio presentation helps a candidate:","stay organized and confident",["sound scripted forever","avoid eye contact","skip examples"],"Preparation builds confidence.")

# ---- 346 Extended Practicum in Education and Training ----
H('346.d.2',3,"A teacher notices students struggle with a lab routine. Advanced problem solving involves:","diagnosing the cause, testing a solution, and checking the results",["assigning blame","skipping labs","repeating the same method"],"Effective problem solving is systematic.")
H('346.d.2',4,"A problem-solving cycle ends with:","evaluating the solution and refining it",["ignoring results","starting over blindly","stopping at the first idea"],"Evaluation completes the cycle.")
H('346.d.1.A',3,"A teacher uses a steady voice, clear words, and open body posture when addressing a class. This shows consistent:","verbal and non-verbal communication",["silent behavior","written-only messaging","avoidance"],"Words and body language align.")
H('346.d.1.A',4,"Which tone best supports clear classroom directions?","Calm and firm",["Sarcastic","Mumbling","Shouting"],"A calm, firm tone communicates authority respectfully.")
H('346.d.1.B',3,"An effective formal presentation to a school committee has:","a clear opening, supporting evidence, and a conclusion",["no structure","only anecdotes","unrelated visuals"],"Structure persuades audiences.")
H('346.d.1.B',4,"An informal presentation, such as a quick update at a team meeting, is usually:","shorter and more conversational",["a legal filing","a written report only","a state exam"],"Informal talks are brief and casual.")
H('346.d.1.C',3,"A teacher reviews quiz results and explains the trends to colleagues. This is:","analyzing and communicating data",["hiding results","guessing","ignoring evidence"],"Data become useful when shared.")
H('346.d.1.C',4,"When communicating data to others, a clear graph is useful because it:","makes patterns easy to see",["hides information","confuses readers","replaces explanation"],"Visuals clarify trends.")
H('346.d.1.D',3,"A student teacher asks, Do you mean the rubric needs more detail? This active-listening move is:","asking a clarifying question",["interrupting","ending the talk","judging"],"Clarifying prevents misunderstanding.")
H('346.d.1.D',4,"Active listening helps obtain accurate information because it:","confirms understanding before acting",["delays decisions","adds confusion","replaces research"],"Confirming prevents errors.")
H('346.d.3.A',3,"A teacher who finishes assigned duties and volunteers to help others shows:","a productive work ethic",["laziness","avoidance","entitlement"],"Initiative marks a strong work ethic.")
H('346.d.3.B',3,"A practicum student discovers an error in the grade book that benefits a friend. Integrity means:","reporting and correcting the error",["leaving it alone","helping hide it","adding to it"],"Honesty requires correction.")
H('346.d.3.A',4,"Punctuality and preparedness are signs of:","reliability",["indifference","disorder","disrespect"],"Reliable people are on time and ready.")
H('346.d.3.B',4,"Honesty in reporting practicum hours means:","recording only the hours actually worked",["rounding up","copying others' logs","estimating high"],"Accurate records show integrity.")
H('346.d.3.C',3,"A district's acceptable-use policy says students and staff must:","use school technology for appropriate purposes",["share passwords","download anything","visit any site"],"AUPs set boundaries for technology.")
H('346.d.3.C',4,"Proper email etiquette for a teacher includes:","using a professional tone and greeting",["using slang","omitting a subject","writing in all caps"],"Professional email is polite and clear.")
H('346.d.3.D',3,"A teacher follows FERPA by:","protecting student education records",["posting grades publicly","sharing records freely","leaving records open"],"FERPA protects privacy of records.")
H('346.d.3.D',4,"Following district policy on field trips, such as signed permission slips, shows:","compliance with rules and regulations",["ignoring policy","optional practice","guessing"],"Compliance protects students and staff.")
H('346.d.4.A',3,"With increased fluency, a student teacher can adjust a lesson when:","students show they have not understood",["a bell rings","lunch arrives","a visitor leaves"],"Fluent teachers respond to evidence.")
H('346.d.4.A',4,"Smooth transitions between lesson parts show:","growing fluency with instructional strategies",["lack of planning","poor timing","confusion"],"Transitions reflect experience.")
H('346.d.4.B',3,"Bloom's revised taxonomy lists create as:","the highest level of thinking",["the lowest level","an unrelated skill","a classroom rule"],"Creating is at the top of the revised taxonomy.")
H('346.d.4.B',4,"Planning that considers students' readiness, interests, and learning profiles applies principles of:","differentiated instruction",["identical instruction","random instruction","unplanned teaching"],"Differentiation tailors teaching.")
H('346.d.4.C',3,"A teacher develops a study guide and practice set for a unit on fractions. This is creating:","curriculum-related instructional materials",["a school budget","a bus plan","a staff schedule"],"Study guides support instruction.")
H('346.d.4.C',4,"Instructional materials should support the objective by:","providing practice that matches the skill being taught",["covering unrelated skills","adding decoration","being longer"],"Materials must target the skill.")
H('346.d.4.D',3,"Core academic subjects include English, math, science, and:","social studies",["lunch","recess","hallway duty"],"Social studies is a foundation subject.")
H('346.d.4.D',4,"Student clubs, fine arts, and CTE courses are examples of:","enrichment opportunities",["punishments","state exams","bus programs"],"Enrichment broadens experience.")
H('346.d.4.E',3,"A lesson plan for a 7th-grade math class should be aligned to:","the grade-level TEKS",["the cafeteria menu","the bus map","the sports calendar"],"Plans must target the standards.")
H('346.d.4.E',4,"An anticipatory set at the start of a lesson is designed to:","capture interest and connect to prior knowledge",["end the lesson","give homework","punish students"],"Hooks engage learners.")
H('346.d.4.F',3,"After teaching, a student teacher writes down strengths, challenges, and next steps. This is:","documenting and reflecting on instruction",["lunch planning","bus duty","attendance"],"Reflection captures learning.")
H('346.d.4.F',4,"To assess an instructional experience, the student teacher can compare:","student results to the lesson objective",["room temperature to the schedule","lunch menus to the objective","bus times to grades"],"Outcomes measure effectiveness.")
H('346.d.4.G',3,"A collection of lesson plans, work samples, and evaluations kept as evidence of teaching skill is a:","portfolio",["roster","grade book","hall pass"],"Portfolios document skill.")
H('346.d.4.G',4,"When collecting student work samples for a portfolio, a student teacher should:","remove names and get required permission",["post names publicly","share without permission","include IDs"],"Student privacy must be protected.")

H('344.d.1.D',4,"A parent describes a toddler's biting at home. Which response best shows attentive listening by the practicum student?","Summarize the concern and ask what the parent has already tried",["Offer a solution before the parent finishes","Change the subject to naptime","Tell the parent it is normal and move on"],"Summarizing and asking questions shows real listening.")

